runbooks.cancel_previous:
apiVersion: therunbook.app/v1
kind: Runbook
metadata: {id: latest, title: latest}
spec:
  defaults: {actor: agent}
  execution: {concurrency: {key: prod, limit: 1, on_conflict: cancel_previous}}
  steps: [{id: work, title: Work}]
  finally: [{id: cleanup, title: Clean up}]

runbooks.queue:
apiVersion: therunbook.app/v1
kind: Runbook
metadata: {id: deploy, title: deploy}
spec:
  defaults: {actor: agent}
  execution: {concurrency: {key: prod, limit: 1, on_conflict: queue}}
  steps: [{id: work, title: Work}]
